#!/usr/bin/env python3
"""cell/dose-response-fit — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "cell"
SKILL = "dose-response-fit"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'ec50': 5.1e-09, 'ec50_ci_low': 3e-09, 'ec50_ci_high': 8.5e-09, 'hill': 1.05, 'top': 100.0, 'bottom': 2.1, 'r2': 0.992, 'plateau_reached': True, 'bell_shape_detected': False, 'plot_png': 'out/dr_curve.png', 'passed_sanity': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """4 参数 Hill 函数 dose-response fit via scipy.optimize.curve_fit。
    输入:doses (list) / responses (list)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    doses = payload.get("doses") or []
    responses = payload.get("responses") or []
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_points": len(doses)}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "ec50": 0.0, "hill": 1.0, "bottom": 0.0, "top": 100.0,
                "ec50_ci_low": 0.0, "ec50_ci_high": 0.0,
                "bell_shape_detected": False,
                "diagnostics": {**diagnostics, "dry": True}}
    if len(doses) != len(responses) or len(doses) < 4:
        return {"ok": False, "error": "需要 doses + responses 同长度 ≥ 4", "diagnostics": diagnostics}
    script = (
        "import json, sys, numpy as np\n"
        "from scipy.optimize import curve_fit\n"
        f"x = np.array({doses!r}, dtype=float); y = np.array({responses!r}, dtype=float)\n"
        "def hill(x, bot, top, ec50, hh):\n"
        "    return bot + (top - bot) / (1 + (ec50/(x+1e-12))**hh)\n"
        "try:\n"
        "    p0 = [float(np.min(y)), float(np.max(y)), float(np.median(x)), 1.0]\n"
        "    popt, pcov = curve_fit(hill, x, y, p0=p0, maxfev=10000)\n"
        "    bot, top, ec50, hh = popt\n"
        "    se = np.sqrt(np.diag(pcov))\n"
        "    bell = bool(np.argmax(y) not in (0, len(y)-1))\n"
        "    json.dump({'ec50': float(ec50), 'hill': float(hh), 'bottom': float(bot), 'top': float(top),\n"
        "               'ec50_ci_low': float(ec50 - 1.96*se[2]), 'ec50_ci_high': float(ec50 + 1.96*se[2]),\n"
        "               'bell_shape_detected': bell}, sys.stdout)\n"
        "except Exception as e:\n"
        "    json.dump({'__err': repr(e)[:200]}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=60)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "fit 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    if "__err" in parsed:
        return {"ok": False, "error": parsed["__err"], "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
